  as t(name text, title text, company text, role text, website_url text);

-- 1. Organizations: any company not already in the table (case-insensitive
-- match), created unclassified (org_type left null, same as the app's own
-- "Unclassified" state).
insert into organizations (name, org_type, website_url)
select distinct on (lower(company)) company, null, website_url
from stg_event_people
where company is not null
order by lower(company), website_url nulls last
on conflict (lower(name)) do nothing;

-- 2. People: anyone not already in the table by exact (case-insensitive)
-- full name match.
insert into people (full_name)
select distinct d.name
from stg_event_people d
where not exists (select 1 from people p where lower(p.full_name) = lower(d.name));

-- 3. Memberships: a current membership at the given company, for anyone
-- who doesn't already have ANY membership there (existing people keep
-- whatever title they already have - this only fills a genuinely missing
-- link, never overwrites).
insert into memberships (person_id, organization_id, title, is_current)
select p.id, o.id, d.title, true
from stg_event_people d
join people p on lower(p.full_name) = lower(d.name)
join organizations o on lower(o.name) = lower(d.company)
where d.company is not null
and not exists (
  select 1 from memberships m where m.person_id = p.id and m.organization_id = o.id
);

-- 4. The event itself, then every attendee's role.
insert into events (name, event_date)
values ('Global Secondaries Summit', '2026-09-22')
on conflict (lower(name), event_date) do nothing;

insert into event_attendees (event_id, person_id, role)
select e.id, p.id, d.role
from stg_event_people d
join people p on lower(p.full_name) = lower(d.name)
cross join (
  select id from events
  where lower(name) = lower('Global Secondaries Summit') and event_date = '2026-09-22'
) e
on conflict (event_id, person_id) do nothing;

commit;

-- Summary, for review after the run (permanent tables only - the staging
-- table is gone once committed).
select
  (select count(*) from events where name = 'Global Secondaries Summit' and event_date = '2026-09-22') as events_row,
  (select count(*) from event_attendees ea join events e on e.id = ea.event_id
     where e.name = 'Global Secondaries Summit' and e.event_date = '2026-09-22') as attendees_linked,
  (select count(*) from memberships m
     join event_attendees ea on ea.person_id = m.person_id
     join events e on e.id = ea.event_id
     where e.name = 'Global Secondaries Summit' and e.event_date = '2026-09-22') as memberships_touched;
